; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_graphics_line:		; sub line (asm keyword), Graphics.cls line 13
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_x0), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_y0), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_x1), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_y1), de
            ld (gfx_sp), sp
            ld sp, (ntc_csp)
            call gfx_line
            ld sp, (gfx_sp)
			ret			; end of #asm

fn_graphics_pen:		; sub pen (asm keyword), Graphics.cls line 67
            pop hl
            ld a, (hl)
            ld (gfx_pen), a
			ret			; end of #asm

fn_graphics_clip:		; sub clip (asm keyword), Graphics.cls line 77
            pop hl
            ld a, (hl)
            or a
            jr z, fn_graphics_clip_cl0
            ld a, 1
fn_graphics_clip_cl0:
            ld (gfx_clip), a
			ret			; end of #asm

fn_keys_down:		; function down (asm keyword), Keys.cls line 44
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ex de, hl
            jp ntc_kdown
			ret			; end of #asm


